// Collect the domains of column "domain" into one list.
const domains = $input.all()
  .map((item) => String(item.json.domain ?? '').trim())
  .filter(Boolean);
if (domains.length === 0) throw new Error('No domain found: add a column named "domain" to the Competitors tab.');
return [{ json: { domains } }];

// One row per domain; the top keywords become a readable text cell.
return $input.all().map(({ json: d }) => ({
  json: {
    date: new Date().toISOString().slice(0, 10),
    domain: d.domain,
    dataFound: d.found,
    organicTraffic: d.organicTraffic ?? null,
    organicKeywords: d.organicKeywords ?? null,
    organicTrafficValueUsd: d.organicTrafficValueUsd ?? null,
    paidTraffic: d.paidTraffic ?? null,
    top3Positions: d.organicPositions ? (d.organicPositions.pos1 ?? 0) + (d.organicPositions.pos2to3 ?? 0) : null,
    topKeywords: (d.topKeywords || [])
      .map((k) => `${k.keyword} (#${k.position}, ${Math.round(k.estimatedTraffic)} visits)`)
      .join(' | '),
    country: d.country,
  },
}));
